void write(juce::Graphics& g,const juce::String& s,juce::Rectangle<int> r,float size=16,juce::Colour color=text,int align=juce::Justification::centredLeft){g.setColour(color);g.setFont(juce::FontOptions(size));g.drawFittedText(s,r,align,1);}
void grid(juce::Graphics& g,juce::Rectangle<float> r){g.setColour(black);g.fillRoundedRectangle(r,3);g.setColour(juce::Colour(0xff343738));for(int i=1;i<8;++i)g.drawVerticalLine(int(r.getX()+i*r.getWidth()/8),r.getY(),r.getBottom());for(int i=1;i<5;++i)g.drawHorizontalLine(int(r.getY()+i*r.getHeight()/5),r.getX(),r.getRight());}
