RaLook::RaLook(){setColour(juce::Label::textColourId,text);setColour(juce::Slider::textBoxTextColourId,text);setColour(juce::Slider::textBoxBackgroundColourId,black);setColour(juce::Slider::textBoxOutlineColourId,juce::Colour(0xff424647));setColour(juce::TextButton::textColourOffId,text);setColour(juce::TextButton::textColourOnId,black);setColour(juce::ComboBox::textColourId,text);setColour(juce::ComboBox::backgroundColourId,black);setColour(juce::PopupMenu::backgroundColourId,juce::Colour(0xff202324));setColour(juce::PopupMenu::highlightedBackgroundColourId,orange);setColour(juce::PopupMenu::highlightedTextColourId,black);}
void RaLook::drawButtonBackground(juce::Graphics& g,juce::Button& b,const juce::Colour&,bool over,bool down){auto r=b.getLocalBounds().toFloat().reduced(1);auto a=b.getToggleState()?orange:juce::Colour(over?0xff45494b:0xff343839);auto z=b.getToggleState()?juce::Colour(0xffed7e00):juce::Colour(0xff202223);if(down)a=a.darker(.2f);g.setGradientFill(juce::ColourGradient(a,0,0,z,0,r.getBottom(),false));g.fillRoundedRectangle(r,6);g.setColour(b.getToggleState()?juce::Colour(0xffffd17b):juce::Colour(0xff7c8182));g.drawRoundedRectangle(r,6,1);g.setColour(juce::Colours::black.withAlpha(.7f));g.drawRoundedRectangle(r.reduced(-.6f),6,1);}
void RaLook::drawRotarySlider(juce::Graphics& g,int x,int y,int w,int h,float pos,float start,float end,juce::Slider&){float size=float(juce::jmin(w,h))-7;auto r=juce::Rectangle<float>(size,size).withCentre({x+w*.5f,y+h*.5f});auto c=r.getCentre();float radius=size*.5f;g.setColour(juce::Colours::black);g.fillEllipse(r.translated(0,2).expanded(1));g.setGradientFill(juce::ColourGradient(juce::Colour(0xff55595a),r.getX(),r.getY(),juce::Colour(0xff111314),r.getRight(),r.getBottom(),false));g.fillEllipse(r);g.setColour(juce::Colour(0xff898d8d));g.drawEllipse(r.reduced(2),1);juce::Path arc;arc.addCentredArc(c.x,c.y,radius+1,radius+1,0,start,end,true);g.setColour(juce::Colour(0xff080909));g.strokePath(arc,juce::PathStrokeType(3));juce::Path active;float angle=start+pos*(end-start);active.addCentredArc(c.x,c.y,radius+1,radius+1,0,start,angle,true);g.setColour(orange);g.strokePath(active,juce::PathStrokeType(3,juce::PathStrokeType::curved,juce::PathStrokeType::rounded));g.setColour(text);g.drawLine(c.x+std::sin(angle)*radius*.58f,c.y-std::cos(angle)*radius*.58f,c.x+std::sin(angle)*radius*.88f,c.y-std::cos(angle)*radius*.88f,2);}
void RaLook::drawToggleButton(juce::Graphics& g,juce::ToggleButton& b,bool over,bool){auto r=juce::Rectangle<float>(17,17).withPosition(3,(b.getHeight()-17)*.5f);g.setColour(b.getToggleState()?orange:juce::Colour(0xff101213));g.fillRoundedRectangle(r,3);g.setColour(over?text:muted);g.drawRoundedRectangle(r,3,1);if(b.getToggleState()){juce::Path p;p.startNewSubPath(r.getX()+3,r.getY()+8);p.lineTo(r.getX()+7,r.getY()+12);p.lineTo(r.getX()+14,r.getY()+4);g.setColour(black);g.strokePath(p,juce::PathStrokeType(2));}write(g,b.getButtonText(),b.getLocalBounds().withTrimmedLeft(27),15);}
void RaLook::drawComboBox(juce::Graphics& g,int w,int h,bool,int,int,int,int,juce::ComboBox&){auto r=juce::Rectangle<float>(0,0,float(w),float(h)).reduced(.5);g.setColour(black);g.fillRoundedRectangle(r,4);g.setColour(juce::Colour(0xff777b7b));g.drawRoundedRectangle(r,4,1);juce::Path p;p.startNewSubPath(float(w-18),h*.43f);p.lineTo(float(w-13),h*.63f);p.lineTo(float(w-8),h*.43f);g.setColour(text);g.strokePath(p,juce::PathStrokeType(1.8f));}
RaControl::RaControl(RaSamplerProcessor& p,const juce::String& parameter,bool small):id(parameter),compact(small){
 const ra::ParamSpec* spec=nullptr;for(auto& s:ra::specs())if(s.id==id){spec=&s;break;}jassert(spec);if(!spec)return;
 label.setText(spec->label,juce::dontSendNotification);label.setJustificationType(juce::Justification::centred);label.setFont(juce::FontOptions(compact?12.f:14.f));addAndMakeVisible(label);
 if(spec->toggle){toggle.setButtonText(spec->label);addAndMakeVisible(toggle);label.setVisible(false);ba=std::make_unique<ra::APVTS::ButtonAttachment>(p.state,id,toggle);}
 else if(!spec->choices.isEmpty()){combo.addItemList(spec->choices,1);addAndMakeVisible(combo);ca=std::make_unique<ra::APVTS::ComboBoxAttachment>(p.state,id,combo);}
 else {slider.setSliderStyle(compact?juce::Slider::LinearBar:juce::Slider::RotaryHorizontalVerticalDrag);slider.setTextBoxStyle(compact?juce::Slider::TextBoxLeft:juce::Slider::TextBoxBelow,false,compact?getWidth():80,19);slider.setDoubleClickReturnValue(true,spec->initial);slider.setPopupDisplayEnabled(false,false,nullptr);slider.setTextValueSuffix(spec->unit.isEmpty()?"":" "+spec->unit);slider.setNumDecimalPlacesToDisplay((spec->id=="root"||spec->id=="polyphony"||spec->id=="transpose"||spec->id=="oscTune"||spec->id=="bendRange")?0:2);
  if(id=="root")slider.textFromValueFunction=[](double v){return juce::MidiMessage::getMidiNoteName(int(v),true,true,3);};
  if(id=="pan")slider.textFromValueFunction=[](double v){return std::abs(v)<.01?juce::String("C"):juce::String(int(std::abs(v)*100))+(v<0?" L":" R");};
  addAndMakeVisible(slider);sa=std::make_unique<ra::APVTS::SliderAttachment>(p.state,id,slider);
  slider.onDragStart=[&p,parameter]{p.setStatus("Editing "+parameter+" · double-click restores default");};
 }

}
void RaControl::resized(){auto r=getLocalBounds();if(toggle.isVisible()){toggle.setBounds(r.reduced(2));return;}if(label.isVisible())label.setBounds(r.removeFromTop(compact?15:19));if(combo.isVisible())combo.setBounds(r.reduced(4,juce::jmax(1,(r.getHeight()-27)/2)));else slider.setBounds(r.reduced(compact?3:4,0));}
void RaWave::paint(juce::Graphics& g){auto r=getLocalBounds().toFloat();grid(g,r);auto s=processor.sample();if(s!=cached||cachedLength!=getWidth()){cached=s;cachedLength=getWidth();waveform.clear();float mid=r.getCentreY();waveform.startNewSubPath(0,mid);for(int x=0;x<getWidth();++x){int a=int(double(x)*s->length()/getWidth()),b=juce::jmin(s->length(),int(double(x+1)*s->length()/getWidth())+1);float peak=0;for(int i=a;i<b;++i)peak=juce::jmax(peak,std::abs(s->audio.getSample(0,i)));waveform.lineTo(float(x),mid-juce::jmin(1.f,peak)*r.getHeight()*.47f);}for(int x=getWidth()-1;x>=0;--x){int a=int(double(x)*s->length()/getWidth()),b=juce::jmin(s->length(),int(double(x+1)*s->length()/getWidth())+1);float peak=0;for(int i=a;i<b;++i)peak=juce::jmax(peak,std::abs(s->audio.getSample(0,i)));waveform.lineTo(float(x),mid+juce::jmin(1.f,peak)*r.getHeight()*.47f);}waveform.closeSubPath();}
 g.setColour(orange);g.fillPath(waveform);g.drawHorizontalLine(getHeight()/2,0,float(getWidth()));float a=processor.value("start")*getWidth(),b=processor.value("end")*getWidth();g.setColour(juce::Colours::black.withAlpha(.65f));g.fillRect(0.f,0.f,a,float(getHeight()));g.fillRect(b,0.f,getWidth()-b,float(getHeight()));
 for(int n=0;n<2;++n){float x=n==0?a:b;g.setColour(text);g.drawVerticalLine(juce::jlimit(0,getWidth()-1,int(x)),0,float(getHeight()));juce::Path t;t.addTriangle(x,float(n==0?0:getHeight()),x+(n==0?10:-10),float(n==0?0:getHeight()),x,float(n==0?12:getHeight()-12));g.fillPath(t);}
 if(processor.value("loop")>.5f){for(auto id:{"loopStart","loopEnd"}){float x=processor.value(id)*getWidth();g.setColour(juce::Colour(0xff62c8d3));float dashes[]={4,4};g.drawDashedLine({x,15,x,float(getHeight()-15)},dashes,2,1);}}
}
void RaWave::mouseDown(const juce::MouseEvent& e){float x=e.position.x/getWidth();if(e.mods.isShiftDown())dragging=std::abs(x-processor.value("loopStart"))<std::abs(x-processor.value("loopEnd"))?"loopStart":"loopEnd";else dragging=std::abs(x-processor.value("start"))<std::abs(x-processor.value("end"))?"start":"end";if(auto* p=processor.state.getParameter(dragging))p->beginChangeGesture();mouseDrag(e);}
void RaWave::mouseDrag(const juce::MouseEvent& e){if(dragging.isEmpty())return;float value=juce::jlimit(0.f,1.f,e.position.x/getWidth());if(processor.value("snap")>.5f)value=ra::snapToTransient(*processor.sample(),value);float gap=1.f/processor.sample()->length();if(dragging=="start")value=juce::jmin(value,processor.value("end")-gap);if(dragging=="end")value=juce::jmax(value,processor.value("start")+gap);if(dragging=="loopStart")value=juce::jlimit(processor.value("start"),juce::jmax(processor.value("start"),processor.value("loopEnd")-gap),value);if(dragging=="loopEnd")value=juce::jlimit(juce::jmin(processor.value("end"),processor.value("loopStart")+gap),processor.value("end"),value);if(auto* p=processor.state.getParameter(dragging))p->setValueNotifyingHost(p->convertTo0to1(value));repaint();}
void RaWave::mouseUp(const juce::MouseEvent&){if(auto* p=processor.state.getParameter(dragging))p->endChangeGesture();dragging.clear();}
void RaFilterGraph::paint(juce::Graphics& g){auto r=getLocalBounds().toFloat();grid(g,r);ra::Biquad f;double rate=processor.getSampleRate()>0?processor.getSampleRate():44100;int type=int(processor.value("filterType"));f.configure(type,rate,processor.value("cutoff"),processor.value("resonance"),processor.value("peqGain"));juce::Path line;for(int x=0;x<getWidth();++x){double hz=20*std::pow(1000.,double(x)/getWidth()),w=juce::MathConstants<double>::twoPi*hz/rate;std::complex<double> z=std::exp(std::complex<double>(0,-w));double mag=std::abs((f.b0+f.b1*z+f.b2*z*z)/(1.+f.a1*z+f.a2*z*z));if(type==1||type==3)mag*=mag;if(processor.value("filterOn")<.5f)mag=1;float y=juce::jlimit(1.f,float(getHeight()-1),float(getHeight()*.35-20*std::log10(juce::jmax(1e-6,mag))*getHeight()/72));if(x==0)line.startNewSubPath(0,y);else line.lineTo(float(x),y);}g.setColour(orange);g.strokePath(line,juce::PathStrokeType(2));line.lineTo(float(getWidth()),float(getHeight()));line.lineTo(0,float(getHeight()));line.closeSubPath();g.setGradientFill(juce::ColourGradient(orange.withAlpha(.25f),0,0,orange.withAlpha(.02f),0,float(getHeight()),false));g.fillPath(line);}
void RaFilterGraph::mouseDrag(const juce::MouseEvent& e){processor.setParameter("cutoff",float(20*std::pow(1000.,juce::jlimit(0.f,1.f,e.position.x/getWidth()))));processor.setParameter("resonance",.1f+juce::jlimit(0.f,1.f,1-e.position.y/getHeight())*4);repaint();}
void RaVelocity::paint(juce::Graphics& g){auto r=getLocalBounds().toFloat();grid(g,r);juce::Path p;p.startNewSubPath(1,float(getHeight()-1));for(int x=1;x<getWidth();++x)p.lineTo(float(x),float(getHeight()-1)*(1-std::pow(float(x)/(getWidth()-1),processor.value("velocityCurve"))));g.setColour(orange);g.strokePath(p,juce::PathStrokeType(2));}
void RaVelocity::mouseDrag(const juce::MouseEvent& e){float x=juce::jlimit(.05f,.95f,e.position.x/getWidth()),y=juce::jlimit(.01f,.99f,1-e.position.y/getHeight());processor.setParameter("velocityCurve",juce::jlimit(.2f,4.f,std::log(y)/std::log(x)));repaint();}
void RaKeyboard::drawWhiteNote(int note,juce::Graphics& g,juce::Rectangle<float> r,bool down,bool over,juce::Colour,juce::Colour){bool root=note==int(processor.value("root"));auto top=down?orange:juce::Colour(0xfff0f0ed),bottom=down?juce::Colour(0xffdb7800):juce::Colour(0xffbabdbc);if(over)top=top.brighter(.12f);g.setGradientFill(juce::ColourGradient(top,r.getX(),r.getY(),bottom,r.getX(),r.getBottom(),false));g.fillRect(r.reduced(.5f));g.setColour(black);g.drawRect(r,1);if(note%12==0)write(g,juce::MidiMessage::getMidiNoteName(note,true,true,3),r.toNearestInt().withTrimmedTop(int(r.getHeight()-23)),12,black,juce::Justification::centred);if(root){g.setColour(orange);g.fillEllipse(r.getCentreX()-3,r.getBottom()-28,6,6);}}
void RaKeyboard::drawBlackNote(int note,juce::Graphics& g,juce::Rectangle<float> r,bool down,bool over,juce::Colour){g.setColour(juce::Colours::black);g.fillRoundedRectangle(r.translated(1,2),2);g.setGradientFill(juce::ColourGradient(down?orange:juce::Colour(over?0xff55595a:0xff373b3c),r.getX(),r.getY(),down?juce::Colour(0xffb05a00):juce::Colour(0xff090b0c),r.getX(),r.getBottom(),false));g.fillRect(r.reduced(1));if(note==int(processor.value("root"))){g.setColour(orange);g.fillEllipse(r.getCentreX()-2,r.getBottom()-9,4,4);}}
